//go:embed metrics.tsv
var metricData string

func generateMetrics(out string) {
	var b, doc bytes.Buffer
	b.WriteString("// Code generated by internal/cmd/themegen; DO NOT EDIT.\npackage theme\n")
	var keys []string
	var rows [][]string
	for _, line := range strings.Split(strings.TrimSpace(metricData), "\n") {
		if strings.HasPrefix(line, "#") {
			continue
		}
		r := strings.Split(line, "\t")
		if len(r) != 4 {
			panic(line)
		}
		_, e := strconv.ParseFloat(r[1], 32)
		must(e)
		rows = append(rows, r)
		keys = append(keys, r[0])
	}
	accessors(&b, "Metrics", "float32", keys)
	b.WriteString("var metricSpecs = [...]metricSpec{\n")
	doc.WriteString("# 尺寸来源\n\n尺寸单位 DIP，等于 Telegram 100% 缩放逻辑像素；不透明度、计数、比例和缩放档位无单位，viewer.loadingMinArc 使用度。这里记录声明，运行规则见各组件对照页。生成命令：`go run ./internal/cmd/themegen`。\n\n| MewTypeUI 键 | Telegram 常量 | 文件:行号 | 值 |\n|---|---|---|---|\n")
	for _, r := range rows {
		fmt.Fprintf(&b, "{%q,%s},\n", r[0], r[1])
		fmt.Fprintf(&doc, "| `%s` | `%s` | %s | %s |\n", r[0], r[2], r[3], r[1])
	}
	b.WriteString("}\n")
	fmt.Fprintf(&doc, "\n共 %d 个数值。Scrollbar.Width 为 10px 总槽宽扣除两侧各 3px 的实际拇指宽 4 DIP。\n\n输入框 FieldMaxHeight=72 与 ExpandedMaxHeight=224 分别保留；ToLatest 的 52×62 是外框，42 是 ripple 区域。\n\n字阶、动效和材质的来源与扩展见 [theme-behavior.md](theme-behavior.md)。\n", len(rows))
	saveGo(out, "theme/metrics_gen.go", b.Bytes())
	save(out, "docs/reference/theme-metrics.md", doc.Bytes())
	fmt.Printf("Generated %d metrics.\n", len(rows))
}
